customize.css:
/* A Sydney-style look: a navy hero band with a centred title, uppercase navigation, red accents, image-first post cards and a dark footer.
   Written for this blog's own markup from the theme's palette and layout; no stylesheet or font was copied. */
:root{color-scheme:light;--fg:#47425d;--bg:#fff;--link:#d65050;--muted:#6f6a85;--rule:#e8e8ee;--code:#f5f5f8;--navy:#00102e;--red:#d65050;--tint:#f5f5f8;--font:system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;--heading-font:system-ui,-apple-system,"Segoe UI",Roboto,sans-serif}
body{background:#fff;color:var(--fg);font-family:system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;line-height:1.7;overflow-x:hidden}
.wrap{max-width:1100px;padding:0 1.25rem 4rem}
a{color:var(--red)}
header.site{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:.75rem 1.5rem;margin:0;padding:1.2rem 0;border:0;background:#fff;box-shadow:0 0 0 100vmax #fff;clip-path:inset(0 -100vmax)}
header.site a.brand{color:var(--navy);font-size:1.55rem;font-weight:700;letter-spacing:-.01em;text-decoration:none}
header.site a.brand::before{content:none}
header.site nav{display:flex;flex-wrap:wrap;align-items:center;gap:.25rem 1.6rem}
header.site nav a{margin:0;color:var(--navy);font-size:.78rem;font-weight:700;letter-spacing:.08em;text-transform:uppercase;text-decoration:none;border-bottom:2px solid transparent;padding:.35rem 0}
header.site nav a::before{content:none}
header.site nav a:hover{color:var(--red);border-bottom-color:var(--red)}
body>.wrap>h1{margin:0;padding:5.5rem 0 .6rem;text-align:center;color:#fff;font-size:clamp(2.2rem,6vw,4rem);font-weight:700;line-height:1.1;letter-spacing:-.01em;background:#0b2253;box-shadow:0 0 0 100vmax #0b2253;clip-path:inset(0 -100vmax)}
body>.wrap>h1+.meta{margin:-1px 0 3rem;padding:0 0 5.5rem;text-align:center;color:#d8def2;font-size:1.15rem;font-weight:400;letter-spacing:0;text-transform:none;background:#0b2253;box-shadow:0 0 0 100vmax #0b2253;clip-path:inset(0 -100vmax)}
h1::before,h2::before,h3::before,ul.posts h2::before{content:none}
h1,h2,h3{color:var(--navy);font-weight:700;line-height:1.2;letter-spacing:-.01em}
h2{font-size:1.5rem}
.meta{color:var(--muted);font-size:.72rem;font-weight:700;letter-spacing:.08em;text-transform:uppercase}
.meta .tag{display:inline-block;margin:0 0 0 .5rem;padding:.12rem .55rem;background:var(--tint);border-radius:2px;color:var(--navy);font-size:.66rem;letter-spacing:.06em;text-decoration:none}
.meta .tag:hover{background:var(--red);color:#fff}
ul.posts{list-style:none;padding:0;margin:0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:2rem 1.75rem}
ul.posts li{position:relative;display:flex;flex-direction:column;margin:0;padding:0 0 1.2rem;border-bottom:3px solid var(--rule);transition:border-color .15s}
ul.posts li:hover{border-bottom-color:var(--red)}
ul.posts .thumb{display:block;aspect-ratio:4/3;overflow:hidden;background:var(--tint);margin-bottom:1rem}
ul.posts .thumb img{width:100%;height:100%;object-fit:cover;border:0;border-radius:0}
ul.posts .meta{order:2;margin:.2rem 0 .5rem}
ul.posts h2{order:1;margin:0 0 .15rem;font-size:1.25rem;line-height:1.3}
ul.posts h2 a{color:var(--navy);text-decoration:none}
ul.posts h2 a:hover{color:var(--red)}
ul.posts p{order:3;margin:0;color:var(--muted);font-size:.95rem}
article{max-width:46rem;margin:3rem auto 0}
article h1{margin:0 0 .4em;font-size:clamp(1.9rem,4vw,2.8rem)}
article a{overflow-wrap:anywhere}
img{border:0;border-radius:3px}
.cover img{border-radius:3px}
blockquote{margin:1.6em 0;padding:.3em 1.4em;border-left:4px solid var(--red);color:var(--navy);font-size:1.1em;font-style:italic}
pre{background:var(--code);border:0;border-radius:4px}
code{background:var(--code);border-radius:3px}
pre code{background:none}
th{background:var(--tint);color:var(--navy)}
th,td{border-color:var(--rule)}
hr{border:0;border-top:1px solid var(--rule)}
.post-nav,.navigation.pagination .nav-links{display:flex;justify-content:space-between;gap:1rem;margin-top:2.5rem}
.post-nav a,.navigation.pagination a{max-width:48%;padding:.7rem 1.4rem;background:var(--navy);color:#fff;font-size:.78rem;font-weight:700;letter-spacing:.08em;text-transform:uppercase;text-decoration:none;border-radius:3px}
.post-nav a:hover,.navigation.pagination a:hover{background:var(--red)}
form[role=search] input,form.subscribe input{padding:.65rem 1rem;border:1px solid var(--rule);border-radius:3px;background:#fff;color:var(--fg)}
form[role=search] button,form.subscribe button{padding:.65rem 1.5rem;border:0;border-radius:3px;background:var(--red);color:#fff;font-weight:700;letter-spacing:.06em;text-transform:uppercase;cursor:pointer}
footer.site{margin:4rem 0 0;padding:1.6rem 0;border:0;background:#1c1c1c;box-shadow:0 0 0 100vmax #1c1c1c;clip-path:inset(0 -100vmax);color:#a9a9b5;font-size:.85rem;text-align:center}
footer.site a{color:#fff}
::selection{background:var(--red);color:#fff}
@media (max-width:900px){ul.posts{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (max-width:560px){ul.posts{grid-template-columns:1fr}body>.wrap>h1{padding-top:3.5rem}body>.wrap>h1+.meta{padding-bottom:3.5rem}header.site nav{gap:.25rem 1rem}}
@media (prefers-reduced-motion:reduce){ul.posts li{transition:none}}
